          if (p.includes("auth") || p.includes("jwt") || p.includes("session")) return "[AUTH MODULE \u2014 highest priority: bypass, token forgery, session fixation]";
          if (p.includes("payment") || p.includes("billing")) return "[PAYMENT MODULE \u2014 highest priority: price manipulation, IDOR on orders]";
