      description: `${vulnerableForms.length} of ${postForms.length} POST form(s) lack anti-CSRF tokens.`,
      evidence: vulnerableForms.map((f) => `Form at ${f.actionUrl} (fields: ${f.fields.join(", ")})`).join("\n"),
