// src/services/repoFiles.service.ts
init_axios2();
var RepoFilesService = class {
  static GITHUB_API_URL = "https://api.github.com";
  /**
   * Get file content from repository
   */
  static async getFileContent(repoFullName, filePath, branch, accessToken) {
    try {
      const response = await axios_default.get(
        `${this.GITHUB_API_URL}/repos/${repoFullName}/contents/${filePath}?ref=${branch}`,
        {
          headers: {
            Authorization: `Bearer ${accessToken}`,
            Accept: "application/vnd.github.v3+json"
          }
        }
      );
      const content = Buffer.from(response.data.content, "base64").toString("utf-8");
      return {
        path: response.data.path,
        content,
        sha: response.data.sha,
        size: response.data.size
      };
    } catch (error51) {
      console.error(`Error fetching file ${filePath}:`, error51.response?.data || error51.message);
      throw new Error(`Failed to fetch file: ${error51.message}`);
    }
  }
  /**
   * Update file content in repository
   */
  static async updateFileContent(repoFullName, filePath, content, sha, branch, commitMessage, accessToken) {
    try {
      await axios_default.put(
        `${this.GITHUB_API_URL}/repos/${repoFullName}/contents/${filePath}`,
        {
          message: commitMessage,
          content: Buffer.from(content).toString("base64"),
          sha,
          branch
        },
        {
          headers: {
            Authorization: `Bearer ${accessToken}`,
            Accept: "application/vnd.github.v3+json"
          }
        }
      );
    } catch (error51) {
      console.error(`Error updating file ${filePath}:`, error51.response?.data || error51.message);
      throw new Error(`Failed to update file: ${error51.message}`);
    }
  }
  /**
   * Get repository tree (file structure)
   */
  static async getRepoTree(repoFullName, branch, accessToken) {
    try {
      const response = await axios_default.get(
        `${this.GITHUB_API_URL}/repos/${repoFullName}/git/trees/${branch}?recursive=1`,
        {
          headers: {
            Authorization: `Bearer ${accessToken}`,
            Accept: "application/vnd.github.v3+json"
          }
        }
      );
      return response.data.tree.filter((item) => item.type === "blob");
    } catch (error51) {
      console.error("Error fetching repo tree:", error51.response?.data || error51.message);
      throw new Error(`Failed to fetch repository tree: ${error51.message}`);
    }
  }
};

